/// <summary>
/// Process definition for Unplanned Count
/// </summary>
class MwmsProcessUnplannedCount extends TFMProcess
{
}

Method.Source:
public void new()
{
    MwmsLogicBlockCreateCountingJournal         jourBlock = MwmsLogicBlockCreateCountingJournal::Construct();
    MwmsLogicBlockCreateCountingJournalLine     lineBlock = MwmsLogicBlockCreateCountingJournalLine::Construct();
    MwmsLogicBlockPostInventoryJournal          postBlock = MwmsLogicBlockPostInventoryJournal::Construct();
    processName = subStr(classId2Name(classIdGet(this)),strLen(classStr(TFMProcess))+2,100);
    description = "@TaskletMobileWMS:Processusedtomakeajournalwithcou";
    super();

    this.addBlock(jourBlock);
    this.addBlock(lineBlock);
    this.addBlock(postBlock);

    this.linkBlocks(jourBlock,lineBlock,'1','1');
    this.linkBlocks(lineBlock, postBlock,'1','1');
}
